'use strict';
/**
 * DEM terrain acceptance tests against a running backend.
 *
 *   node preview-tools/terrain-api-test.js
 *
 * Environment: API_BASE (default http://127.0.0.1:3000), TOKEN_FILE, OTHER_TOKEN_FILE.
 * Fixtures are generated by preview-tools/fixtures/make-fixtures.py with numpy/rasterio, so the
 * expected statistics below are independent of geotiff.js.
 */

const fs = require('fs');
const path = require('path');
const crypto = require('crypto');

const API = process.env.API_BASE || 'http://127.0.0.1:3000';
const FIXTURES = path.join(__dirname, 'fixtures');
const UPLOADS = path.join(__dirname, '..', 'backend', 'uploads');
const PROJECT = 1;
const TOKEN = fs.readFileSync(process.env.TOKEN_FILE || '/tmp/dem-token.txt', 'utf8').trim();
const OTHER_TOKEN = fs.readFileSync(process.env.OTHER_TOKEN_FILE || '/tmp/other-token.txt', 'utf8').trim();
const expected = JSON.parse(fs.readFileSync(path.join(FIXTURES, 'expected.json'), 'utf8'));

const results = [];
function check(name, condition, detail = '') {
  results.push({ name, ok: Boolean(condition), detail });
  console.log(`${condition ? 'PASS' : 'FAIL'}  ${name}${detail ? ` — ${detail}` : ''}`);
}
const sha = buffer => crypto.createHash('sha256').update(buffer).digest('hex');
const close = (a, b, tolerance) => Math.abs(Number(a) - Number(b)) <= tolerance;

async function request(url, { token = TOKEN, method = 'GET', body, raw = false } = {}) {
  const headers = token ? { Authorization: `Bearer ${token}` } : {};
  const response = await fetch(`${API}${url}`, { method, headers, body });
  if (raw) return response;
  const text = await response.text();
  let data;
  try { data = JSON.parse(text); } catch { data = text; }
  return { status: response.status, data, headers: response.headers };
}

async function upload(fileName, token = TOKEN) {
  const buffer = fs.readFileSync(path.join(FIXTURES, fileName));
  const form = new FormData();
  form.append('file', new Blob([buffer]), fileName);
  const response = await fetch(`${API}/api/terrain/${PROJECT}/upload`, {
    method: 'POST',
    headers: { Authorization: `Bearer ${token}` },
    body: form
  });
  const text = await response.text();
  let data;
  try { data = JSON.parse(text); } catch { data = text; }
  return { status: response.status, data, bytes: buffer.length };
}

async function previewBuffer(surveyId, token = TOKEN) {
  const response = await request(`/api/terrain/${PROJECT}/${surveyId}/preview.bin`, { token, raw: true });
  const buffer = Buffer.from(await response.arrayBuffer());
  return { status: response.status, buffer, width: Number(response.headers.get('x-preview-width')), height: Number(response.headers.get('x-preview-height')) };
}

function walk(dir) {
  if (!fs.existsSync(dir)) return [];
  return fs.readdirSync(dir, { withFileTypes: true }).flatMap(entry => {
    const full = path.join(dir, entry.name);
    return entry.isDirectory() ? walk(full) : [full];
  });
}

(async () => {
  console.log(`\nDEM acceptance tests against ${API}\n` + '='.repeat(72));

  const before = await request(`/api/terrain/${PROJECT}`);
  const baselineCount = Array.isArray(before.data) ? before.data.length : -1;
  check('0. authenticated list loads', before.status === 200 && Array.isArray(before.data), `HTTP ${before.status}, ${baselineCount} records`);

  // ---- 1. valid upload -----------------------------------------------------
  const valid = await upload('valid-utm37-dem.tif');
  const survey = valid.data.survey || {};
  check('1a. valid GeoTIFF accepted', valid.status === 201 && survey.status === 'ready', `HTTP ${valid.status}`);
  check('1b. CRS read from GeoKeys, not guessed', survey.epsg === expected.valid.epsg && survey.crs === 'EPSG:32637', survey.crs);
  check('1c. original file size recorded', Number(survey.fileBytes) === valid.bytes, `${survey.fileBytes} bytes`);

  // ---- 6. statistics vs independent numpy ground truth --------------------
  const stats = survey.statistics || {};
  check('6a. minimum matches numpy', close(stats.min, expected.valid.min, 0.01), `${stats.min} vs ${expected.valid.min}`);
  check('6b. maximum matches numpy', close(stats.max, expected.valid.max, 0.01), `${stats.max} vs ${expected.valid.max}`);
  check('6c. mean matches numpy', close(stats.mean, expected.valid.mean, 0.05), `${stats.mean?.toFixed(3)} vs ${expected.valid.mean.toFixed(3)}`);

  // ---- 7. bounds and pixel size ------------------------------------------
  const bounds = survey.bounds || [];
  check('7a. bounds match the geotransform', bounds.length === 4 && bounds.every((v, i) => close(v, expected.valid.bounds[i], 1e-6)), JSON.stringify(bounds));
  check('7b. pixel size is 2 m × 2 m', close(survey.pixelSize.x, 2, 1e-9) && close(survey.pixelSize.y, 2, 1e-9), JSON.stringify(survey.pixelSize));

  // ---- 5. NoData ----------------------------------------------------------
  const validPreview = await previewBuffer(survey.id);
  const cells = new Float32Array(validPreview.buffer.buffer, validPreview.buffer.byteOffset, validPreview.buffer.length / 4);
  let nanCount = 0;
  let sawNoDataSentinel = false;
  for (const value of cells) {
    if (Number.isNaN(value)) nanCount += 1;
    if (value === expected.valid.nodata) sawNoDataSentinel = true;
  }
  check('5a. NoData is NaN in the preview grid, not -9999', nanCount > 0 && !sawNoDataSentinel, `${nanCount} NaN cells, sentinel present: ${sawNoDataSentinel}`);
  check('5b. NoData excluded from statistics', stats.min > expected.valid.nodata, `min ${stats.min}`);
  check('5c. preview grid has the source dimensions (300 × 200)', validPreview.width === 300 && validPreview.height === 200 && cells.length === 60000, `${validPreview.width}×${validPreview.height}, ${cells.length} cells`);

  // ---- 12. original file preservation ------------------------------------
  const originalSha = sha(fs.readFileSync(path.join(FIXTURES, 'valid-utm37-dem.tif')));
  const storedFiles = walk(UPLOADS).filter(file => file.endsWith('.tif'));
  const preserved = storedFiles.map(file => sha(fs.readFileSync(file))).includes(originalSha);
  check('12a. stored file is byte-identical to the upload', preserved, `${storedFiles.length} stored GeoTIFFs`);
  check('12b. API exposes the same SHA-256', survey.sha256 === originalSha, survey.sha256?.slice(0, 16));

  // ---- 2. invalid file ----------------------------------------------------
  const countBeforeInvalid = (await request(`/api/terrain/${PROJECT}`)).data.length;
  const png = await upload('not-a-tiff.png');
  const countAfterInvalid = (await request(`/api/terrain/${PROJECT}`)).data.length;
  check('2a. non-TIFF rejected on signature', png.status === 422 && /not a TIFF/i.test(png.data.error || ''), `HTTP ${png.status}: ${png.data.error}`);
  check('2b. rejected signature creates no record', countAfterInvalid === countBeforeInvalid, `${countBeforeInvalid} → ${countAfterInvalid}`);

  // ---- 3. missing CRS ----------------------------------------------------
  const noCrs = await upload('missing-crs.tif');
  check('3a. missing CRS refused, not guessed', noCrs.status === 422 && /no CRS recorded/i.test(noCrs.data.error || ''), `HTTP ${noCrs.status}`);
  const afterNoCrs = (await request(`/api/terrain/${PROJECT}`)).data;
  const noCrsRecord = afterNoCrs.find(record => record.id === noCrs.data.survey?.id);
  check('3b. failed attempt is recorded with status=failed', noCrsRecord?.status === 'failed' && Boolean(noCrsRecord?.error), noCrsRecord?.error?.slice(0, 60));

  // ---- 4. unsupported CRS ------------------------------------------------
  const mercator = await upload('unsupported-mercator.tif');
  check('4a. Web Mercator refused with its code', mercator.status === 422 && /EPSG:3857/.test(mercator.data.error || ''), mercator.data.error?.slice(0, 90));

  // ---- 13. corrupt file / failure recovery -------------------------------
  const corrupt = await upload('corrupt-header.tif');
  const corruptRecord = (await request(`/api/terrain/${PROJECT}`)).data.find(record => record.id === corrupt.data.survey?.id);
  check('13a. corrupt TIFF rejected with a record', corrupt.status === 422 && corruptRecord?.status === 'failed', `HTTP ${corrupt.status}, status ${corruptRecord?.status}`);
  check('13b. failure reason stored for the user', Boolean(corruptRecord?.error), corruptRecord?.error?.slice(0, 80));
  const corruptBytes = fs.readFileSync(path.join(FIXTURES, 'corrupt-header.tif'));
  const failedFilePreserved = walk(UPLOADS).some(file => file.endsWith('.tif') && sha(fs.readFileSync(file)) === sha(corruptBytes));
  check('13c. corrupt upload file removed after failure', !failedFilePreserved, `${walk(UPLOADS).filter(f => f.endsWith('.tif')).length} GeoTIFFs remain`);
  const deleted = await request(`/api/terrain/${PROJECT}/${corrupt.data.survey.id}`, { method: 'DELETE' });
  check('13d. failed record can be deleted', deleted.status === 200, `HTTP ${deleted.status}`);

  // ---- 8. large raster: windowed read + 512 preview ----------------------
  const started = Date.now();
  const large = await upload('large-2000x2000-dem.tif');
  const largeMs = Date.now() - started;
  const largeSurvey = large.data.survey || {};
  check('8a. 2000 × 2000 DEM accepted', large.status === 201 && largeSurvey.status === 'ready', `HTTP ${large.status} in ${largeMs} ms`);
  check('8b. large-DEM statistics match numpy', close(largeSurvey.statistics.min, expected.large.min, 0.01) && close(largeSurvey.statistics.max, expected.large.max, 0.01),
    `${largeSurvey.statistics.min}–${largeSurvey.statistics.max}`);
  check('8c. preview is capped at 512 × 512', largeSurvey.preview.width === 512 && largeSurvey.preview.height === 512, JSON.stringify(largeSurvey.preview));
  const largePreview = await previewBuffer(largeSurvey.id);
  const largeCells = new Float32Array(largePreview.buffer.buffer, largePreview.buffer.byteOffset, largePreview.buffer.length / 4);
  check('8d. preview binary is 512 × 512 float32', largePreview.buffer.length === 512 * 512 * 4 && largeCells.length === 262144, `${largePreview.buffer.length} bytes`);
  let previewMin = Infinity;
  for (const value of largeCells) if (!Number.isNaN(value) && value < previewMin) previewMin = value;
  check('8e. preview values stay inside the source range', previewMin >= largeSurvey.statistics.min - 0.01, `preview min ${previewMin} ≥ source min ${largeSurvey.statistics.min}`);

  // ---- 10. authentication and ownership ---------------------------------
  const anon = await request(`/api/terrain/${PROJECT}`, { token: null });
  const foreign = await request(`/api/terrain/${PROJECT}`, { token: OTHER_TOKEN });
  const foreignPreview = await request(`/api/terrain/${PROJECT}/${largeSurvey.id}/preview`, { token: OTHER_TOKEN });
  check('10a. unauthenticated request is 401', anon.status === 401, `HTTP ${anon.status}`);
  check('10b. another user gets 404, not data', foreign.status === 404 && foreignPreview.status === 404, `list ${foreign.status}, preview ${foreignPreview.status}`);
  check('10c. another user cannot upload', (await upload('valid-utm37-dem.tif', OTHER_TOKEN)).status === 404);

  // ---- derivatives -------------------------------------------------------
  const hillshade = await request(`/api/terrain/${PROJECT}/${largeSurvey.id}/hillshade.png`, { raw: true });
  const hillshadeBuffer = Buffer.from(await hillshade.arrayBuffer());
  check('8f. hillshade PNG generated from the preview', hillshade.status === 200 && hillshadeBuffer.subarray(0, 8).equals(Buffer.from([137, 80, 78, 71, 13, 10, 26, 10])), `${hillshadeBuffer.length} bytes`);
  const slope = await request(`/api/terrain/${PROJECT}/${largeSurvey.id}/slope.png`, { raw: true });
  const aspect = await request(`/api/terrain/${PROJECT}/${largeSurvey.id}/aspect.png`, { raw: true });
  check('8g. slope and aspect PNGs generated', slope.status === 200 && aspect.status === 200, `slope ${slope.status}, aspect ${aspect.status}`);
  const contours = await request(`/api/terrain/${PROJECT}/${largeSurvey.id}/contours?interval=20`);
  check('8h. contours are GeoJSON and labelled preview-derived', contours.status === 200 && contours.data.type === 'FeatureCollection' && contours.data.metadata?.previewDerived === true, `${contours.data.features?.length} segments`);

  // ---- benchmarks --------------------------------------------------------
  const benchmarks = await request(`/api/terrain/${PROJECT}/${survey.id}/benchmarks`);
  const compared = (benchmarks.data.results || []).filter(row => row.status === 'compared');
  check('b1. benchmark comparison reports differences', benchmarks.status === 200 && compared.length === 2, `${compared.length} points compared`);
  check('b2. differences are benchmark − DEM (no adjustment)', compared.every(row => close(row.difference, row.benchmarkElevation - row.demElevation, 0.011)), JSON.stringify(compared.map(r => r.difference)));
  check('b3. response states nothing was shifted', /not been adjusted/i.test(benchmarks.data.note || ''), benchmarks.data.note);

  // ---- regressions -------------------------------------------------------
  const projects = await request('/api/projects');
  const model = await request('/api/3d/model/1');
  const surveying = await request('/api/surveying/1');
  const quantity = await request('/api/quantity-survey/1');
  const catalogue = await request('/api/gis/catalogue');
  const datasets = await request('/api/gis/datasets/1');
  check('r1. projects endpoint unchanged', projects.status === 200 && projects.data.some(p => p.id === PROJECT), `HTTP ${projects.status}`);
  check('r2. BIM/3D components endpoint unchanged', model.status === 200 && model.data.components.length === 17, `${model.data.components?.length} components`);
  check('r3. surveying endpoint unchanged', surveying.status === 200, `HTTP ${surveying.status}`);
  check('r4. quantity survey endpoint unchanged', quantity.status === 200, `HTTP ${quantity.status}`);
  check('r5. GIS catalogue still responds', catalogue.status === 200 && Boolean(catalogue.data.crs), `HTTP ${catalogue.status}`);
  check('r6. GIS datasets still respond', datasets.status === 200 && Array.isArray(datasets.data), `${datasets.data.length} datasets`);

  const passed = results.filter(result => result.ok).length;
  const failed = results.length - passed;
  console.log('='.repeat(72));
  console.log(`${passed}/${results.length} checks passed, ${failed} failed`);
  fs.writeFileSync(path.join(__dirname, 'terrain-test-results.json'), JSON.stringify({ api: API, at: new Date().toISOString(), passed, failed, results }, null, 2));
  process.exit(failed === 0 ? 0 : 1);
})().catch(error => {
  console.error('Test run aborted:', error);
  process.exit(2);
});
